<?php
 namespace QQWorld\Captcha\Observer; use QQWorld\Framework\Event\ObserverInterface; class CheckGuestCheckoutObserver implements ObserverInterface { protected $_helper; protected $_actionFlag; protected $captchaStringResolver; protected $_typeOnepage; protected $jsonHelper; public function __construct( \QQWorld\Captcha\Helper\Data $helper, \QQWorld\Framework\App\ActionFlag $actionFlag, CaptchaStringResolver $captchaStringResolver, \QQWorld\Checkout\Model\Type\Onepage $typeOnepage, \QQWorld\Framework\Json\Helper\Data $jsonHelper ) { $this->_helper = $helper; $this->_actionFlag = $actionFlag; $this->captchaStringResolver = $captchaStringResolver; $this->_typeOnepage = $typeOnepage; $this->jsonHelper = $jsonHelper; } public function execute(\QQWorld\Framework\Event\Observer $observer) { $formId = 'guest_checkout'; $captchaModel = $this->_helper->getCaptcha($formId); $checkoutMethod = $this->_typeOnepage->getQuote()->getCheckoutMethod(); if ($checkoutMethod == \QQWorld\Checkout\Model\Type\Onepage::METHOD_GUEST) { if ($captchaModel->isRequired()) { $controller = $observer->getControllerAction(); if (!$captchaModel->isCorrect($this->captchaStringResolver->resolve($controller->getRequest(), $formId)) ) { $this->_actionFlag->set('', \QQWorld\Framework\App\Action\Action::FLAG_NO_DISPATCH, true); $result = ['error' => 1, 'message' => __('Incorrect CAPTCHA')]; $controller->getResponse()->representJson($this->jsonHelper->jsonEncode($result)); } } } return $this; } } 